/**
 * @fileoverview Defines the EndFlow type and function for terminating a flow execution.
 * This module is part of the Fluent Flow Logic system.
 */
/**
 * Represents an EndFlow operation in a flow.
 *
 * @typedef {Object} EndFlow
 * @property {string} [annotation] - Optional annotation/comment describing why the flow is ending
 * @extends Now.Internal.WithID - Includes a unique identifier for the flow operation
 */
type EndFlowType = Now.Internal.WithID<{
    annotation?: string;
}>;
/**
 * Terminates the current flow execution.
 * When this function is called, the flow execution will stop and no further actions will be processed.
 *
 * @param {EndFlowType} endFlow - The EndFlow configuration object
 * @returns {void}
 *
 * @example
 * // End a flow with an annotation
 * EndFlow({
 *   $id: 'end-flow-1',
 *   annotation: 'Process completed successfully'
 * });
 *
 * @example
 * // End a flow without an annotation
 * EndFlow({
 *   $id: 'end-flow-2'
 * });
 */
export declare function EndFlow(endFlow: EndFlowType): {
    type: 'endflow';
};
export {};
